public static int findStation(int[] gas, int[] cost){
    int n = gas.length;
    int tgas = 0;
    int tcost = 0;
    for (int i=0; i<n; i++){
        tgas = tgas + gas[i];
        tcost = tcost + cost[i];
    }

    if (tgas<tcost) return -1;

    int ans = 0;
    int currentGas = 0;
    for (int i=0; i<n; i++){
        currentGas = currentGas + gas[i] - cost[i];
        if (currentGas<0){
            ans = i+1;
            currentGas=0;
        }
    }
    return ans;
}
